sp_widget.client_script:
api.controller = function() {

    var c = this;


    /* ======================================================
       DONUT CALCULATION
    ====================================================== */

    c.donutStyle = function(
        value,
        total
    ) {

        if (!total) {

            return {
                strokeDasharray:
                    '0 100'
            };

        }


        var percent =
            (
                value /
                total
            ) * 100;


        return {

            strokeDasharray:
                percent +
                ' ' +
                (
                    100 -
                    percent
                )

        };

    };



    /* ======================================================
       CATEGORY MAX
    ====================================================== */

    c.maxCategory =
        function() {

            var categories =
                c.data.categories || [];


            var max = 1;


            categories.forEach(
                function(category) {

                    if (
                        category.total >
                        max
                    ) {

                        max =
                            category.total;

                    }

                }
            );


            return max;

        };



    /* ======================================================
       CATEGORY WIDTH
    ====================================================== */

    c.categoryWidth =
        function(category) {

            var max =
                c.maxCategory();


            return {

                width:
                    (
                        (
                            category.total /
                            max
                        ) * 100
                    ) +
                    '%'

            };

        };



    /* ======================================================
       MATCH WIDTH
    ====================================================== */

    c.matchWidth =
        function(value) {

            var total =
                c.data.summary
                    .totalMatches ||
                1;


            return {

                width:
                    (
                        (
                            value /
                            total
                        ) * 100
                    ) +
                    '%'

            };

        };



    /* ======================================================
       CLAIM WIDTH
    ====================================================== */

    c.claimWidth =
        function(value) {

            var total =
                c.data.summary
                    .totalClaims ||
                1;


            return {

                width:
                    (
                        (
                            value /
                            total
                        ) * 100
                    ) +
                    '%'

            };

        };

};

sp_widget.css:
/* =========================================================
   CAMPUSMATCH ADMIN ANALYTICS
   WEBSITE + NOW MOBILE APP
   FULL-BLEED SAFE VERSION
========================================================= */

.cm-analytics,
.cm-analytics * {
  box-sizing: border-box;
}


.cm-analytics {
  position: relative;
  display: block;

  /* FULL-BLEED HORIZONTAL FIX */
  width: 100vw !important;
  max-width: 100vw !important;

  margin-left: calc(50% - 50vw) !important;
  margin-right: calc(50% - 50vw) !important;

  margin-top: 0 !important;
  margin-bottom: 0 !important;

  min-height: 100vh;
  min-height: 100svh;

  padding: 28px;

  background: #FBF8EF !important;

  /*
     Covers ServiceNow outer top/bottom gaps
     without touching Header.
  */
  box-shadow:
    0 -60px 0 #FBF8EF,
    0 60px 0 #FBF8EF;

  color: #102E34;

  font-family:
    "Plus Jakarta Sans",
    Arial,
    sans-serif;

  overflow-x: hidden;
}


/* =========================================================
   HEADER
========================================================= */

.cm-analytics-header {
  margin-bottom: 22px;
}


.cm-analytics-header span,
.cm-chart-heading span {
  color: #249D78;

  font-size: 9px;
  font-weight: 800;

  letter-spacing: 1.3px;

  text-transform: uppercase;
}


.cm-analytics-header h2 {
  margin: 6px 0 7px;

  color: #104E45;

  font-size: 27px;
  font-weight: 800;
}


.cm-analytics-header p {
  margin: 0;

  color: #506267;

  font-size: 11px;
  line-height: 1.6;
}


/* =========================================================
   TOP METRIC CARDS
========================================================= */

.cm-metric-grid {
  margin-bottom: 20px;

  display: grid;

  grid-template-columns:
    repeat(4, minmax(0, 1fr));

  gap: 14px;
}


.cm-metric-card {
  position: relative;

  overflow: hidden;

  min-height: 105px;

  padding: 20px;

  border: 1px solid #D2DED8;

  border-radius: 20px;

  background: #FFFFFF;

  box-shadow:
    0 6px 20px rgba(16, 78, 69, 0.06);

  transition:
    transform 0.2s ease,
    box-shadow 0.2s ease,
    border-color 0.2s ease;
}


.cm-metric-card:hover {
  transform: translateY(-2px);

  border-color: #249D78;

  box-shadow:
    0 9px 24px rgba(16, 78, 69, 0.10);
}


.cm-metric-card::before {
  content: "";

  position: absolute;

  top: 0;
  left: 0;

  width: 100%;
  height: 4px;

  background: #249D78;
}


.cm-metric-card span {
  display: block;

  color: #506267;

  font-size: 8px;
  font-weight: 800;

  letter-spacing: 0.9px;
}


.cm-metric-card strong {
  display: block;

  margin-top: 9px;

  color: #104E45;

  font-size: 28px;
  font-weight: 800;
}


/* =========================================================
   MAIN GRID
========================================================= */

.cm-analytics-grid {
  margin-bottom: 20px;

  display: grid;

  grid-template-columns:
    repeat(2, minmax(0, 1fr));

  gap: 20px;
}


/* =========================================================
   CHART CARDS
========================================================= */

.cm-chart-card {
  min-width: 0;

  padding: 22px;

  border: 1px solid #D2DED8;

  border-radius: 22px;

  background: #FFFFFF;

  box-shadow:
    0 6px 22px rgba(16, 78, 69, 0.055);
}


.cm-full-chart {
  margin-bottom: 20px;
}


.cm-chart-heading {
  margin-bottom: 20px;
}


.cm-chart-heading h3 {
  margin: 5px 0 0;

  color: #104E45;

  font-size: 18px;
  font-weight: 700;
}


/* =========================================================
   DONUT
========================================================= */

.cm-donut-area {
  display: flex;

  align-items: center;

  gap: 32px;
}


.cm-donut {
  position: relative;

  flex-shrink: 0;

  width: 150px;
  height: 150px;
}


.cm-donut svg {
  width: 100%;
  height: 100%;

  transform: rotate(-90deg);
}


.cm-donut-base {
  fill: none;

  stroke: #EDF5E9;

  stroke-width: 5;
}


.cm-donut-lost {
  fill: none;

  stroke: #104E45;

  stroke-width: 5;

  stroke-dasharray: 0 100;

  stroke-linecap: round;

  transition:
    stroke-dasharray 0.4s ease;
}


.cm-donut-center {
  position: absolute;

  inset: 0;

  display: flex;

  align-items: center;
  justify-content: center;
  flex-direction: column;
}


.cm-donut-center strong {
  color: #104E45;

  font-size: 27px;
  font-weight: 800;
}


.cm-donut-center span {
  margin-top: 2px;

  color: #506267;

  font-size: 9px;
  font-weight: 600;
}


/* =========================================================
   DONUT LEGEND
========================================================= */

.cm-donut-legend {
  flex: 1;
}


.cm-donut-legend > div {
  padding: 10px 0;

  display: grid;

  grid-template-columns:
    11px 1fr auto;

  align-items: center;

  gap: 9px;

  border-bottom: 1px solid #EDF5E9;
}


.cm-donut-legend > div:last-child {
  border-bottom: 0;
}


.cm-donut-legend p {
  margin: 0;

  color: #506267;

  font-size: 10px;
  font-weight: 600;
}


.cm-donut-legend strong {
  color: #104E45;

  font-size: 12px;
  font-weight: 800;
}


.cm-legend-dot {
  width: 9px;
  height: 9px;

  border-radius: 50%;
}


.cm-legend-dot.lost {
  background: #104E45;
}


.cm-legend-dot.found {
  background: #249D78;
}


/* =========================================================
   LIFECYCLE
========================================================= */

.cm-lifecycle {
  min-height: 150px;

  display: flex;

  align-items: center;
  justify-content: space-between;

  gap: 9px;
}


.cm-life-stat {
  flex: 1;

  min-width: 0;

  padding: 16px 8px;

  text-align: center;

  border: 1px solid #D2DED8;

  border-radius: 16px;

  background: #EDF5E9;
}


.cm-life-stat strong {
  display: block;

  color: #104E45;

  font-size: 21px;
  font-weight: 800;
}


.cm-life-stat span {
  display: block;

  margin-top: 6px;

  color: #506267;

  font-size: 8px;
  font-weight: 600;

  line-height: 1.35;
}


.cm-life-arrow {
  color: #249D78;

  font-size: 17px;
  font-weight: 800;
}


/* =========================================================
   CATEGORY DISTRIBUTION
========================================================= */

.cm-category-row {
  padding: 11px 0;

  display: grid;

  grid-template-columns:
    180px
    minmax(0, 1fr)
    40px;

  align-items: center;

  gap: 14px;

  border-bottom: 1px solid #EDF5E9;
}


.cm-category-row:last-child {
  border-bottom: 0;
}


.cm-category-label strong,
.cm-category-label span {
  display: block;
}


.cm-category-label strong {
  color: #102E34;

  font-size: 10px;
  font-weight: 700;
}


.cm-category-label span {
  margin-top: 4px;

  color: #506267;

  font-size: 8px;
}


.cm-category-track,
.cm-quality-track {
  height: 10px;

  overflow: hidden;

  border-radius: 999px;

  background: #EDF5E9;
}


.cm-category-bar {
  height: 100%;

  min-width: 3px;

  border-radius: inherit;

  background: #249D78;

  transition:
    width 0.4s ease;
}


.cm-category-total {
  text-align: right;

  color: #104E45;

  font-size: 12px;
  font-weight: 800;
}


/* =========================================================
   MATCH QUALITY / CLAIM QUALITY
========================================================= */

.cm-quality-row {
  margin: 17px 0;
}


.cm-quality-label {
  margin-bottom: 8px;

  display: flex;

  align-items: center;
  justify-content: space-between;

  gap: 10px;
}


.cm-quality-label span {
  color: #102E34;

  font-size: 9px;
  font-weight: 700;
}


.cm-quality-label strong {
  color: #104E45;

  font-size: 11px;
  font-weight: 800;
}


.cm-quality-track {
  height: 11px;
}


.cm-quality-bar {
  height: 100%;

  min-width: 0;

  border-radius: inherit;

  transition:
    width 0.4s ease;
}


/* =========================================================
   MATCH QUALITY COLORS
========================================================= */

.cm-quality-bar.strong {
  background: #249D78;
}


.cm-quality-bar.potential {
  background: #168C70;
}


.cm-quality-bar.low {
  background: #506267;
}


/* =========================================================
   CLAIM VERIFICATION COLORS
========================================================= */

.cm-quality-bar.pass {
  background: #249D78;
}


.cm-quality-bar.review {
  background: #168C70;
}


.cm-quality-bar.fail {
  background: #104E45;
}


/* =========================================================
   ACCESS DENIED
========================================================= */

.cm-analytics-denied {
  padding: 34px;

  text-align: center;

  border: 1px solid #D2DED8;

  border-radius: 20px;

  background: #EDF5E9;

  color: #104E45;

  font-size: 12px;
  font-weight: 700;
}


/* =========================================================
   RESPONSIVE — TABLET
========================================================= */

@media (max-width: 900px) {

  .cm-analytics {
    padding: 22px;

    box-shadow:
      0 -60px 0 #FBF8EF,
      0 60px 0 #FBF8EF;
  }


  .cm-metric-grid {
    grid-template-columns:
      repeat(2, minmax(0, 1fr));
  }


  .cm-analytics-grid {
    grid-template-columns: 1fr;
  }

}


/* =========================================================
   RESPONSIVE — MOBILE
========================================================= */

@media (max-width: 600px) {

  .cm-analytics {
    min-height: 100svh;

    padding:
      18px
      14px;

    box-shadow:
      0 -60px 0 #FBF8EF,
      0 60px 0 #FBF8EF;
  }


  .cm-analytics-header h2 {
    font-size: 23px;
  }


  .cm-metric-grid {
    grid-template-columns:
      repeat(2, minmax(0, 1fr));

    gap: 10px;
  }


  .cm-metric-card {
    min-height: 90px;

    padding: 15px;

    border-radius: 16px;
  }


  .cm-metric-card strong {
    font-size: 23px;
  }


  .cm-chart-card {
    padding: 17px;

    border-radius: 18px;
  }


  .cm-donut-area {
    flex-direction: column;

    align-items: stretch;

    gap: 18px;
  }


  .cm-donut {
    margin: 0 auto;
  }


  .cm-lifecycle {
    display: grid;

    grid-template-columns:
      repeat(2, minmax(0, 1fr));

    gap: 9px;

    min-height: 0;
  }


  .cm-life-arrow {
    display: none;
  }


  .cm-category-row {
    grid-template-columns:
      110px
      minmax(0, 1fr)
      28px;

    gap: 9px;
  }

}


/* =========================================================
   EXTRA SMALL MOBILE
========================================================= */

@media (max-width: 390px) {

  .cm-analytics {
    padding-left: 10px;
    padding-right: 10px;
  }


  .cm-metric-grid {
    grid-template-columns:
      1fr 1fr;
  }


  .cm-category-row {
    grid-template-columns:
      95px
      minmax(0, 1fr)
      25px;
  }

}

sp_widget.script:
(function() {

    /* ======================================================
       TABLES
    ====================================================== */

    var ITEM_TABLE =
        'x_snc_campusmatch_campusmatch_item';

    var MATCH_TABLE =
        'x_snc_campusmatch_campusmatch_match';

    var CLAIM_TABLE =
        'x_snc_campusmatch_campusmatch_claim';


    /* ======================================================
       TASK 14 - CAMPUSMATCH STAFF SECURITY
    ====================================================== */

    var access =
        new CampusMatchAccess();


    data.isStaff =
        access.isStaff();


    /*
     * Keep this temporarily in case existing HTML
     * still refers to data.isAdmin.
     */
    data.isAdmin =
        data.isStaff;


    data.allowed =
        data.isStaff;


    /*
     * IMPORTANT:
     * Stop before querying any analytics data.
     */
    if (!data.allowed) {

        return;

    }


    /* ======================================================
       OUTPUT
    ====================================================== */

    data.summary = {

        totalReports: 0,

        lost: 0,

        found: 0,

        resolved: 0,

        active: 0,

        totalMatches: 0,

        strongMatches: 0,

        potentialMatches: 0,

        lowMatches: 0,

        totalClaims: 0,

        claimPass: 0,

        claimReview: 0,

        claimFail: 0

    };


    data.categories = [];


    /* ======================================================
       ITEM ANALYTICS
    ====================================================== */

    var categoryMap = {};


    var item =
        new GlideRecord(
            ITEM_TABLE
        );


    item.query();


    while (item.next()) {

        data.summary.totalReports++;


        var type =
            (
                item.getValue(
                    'report_type'
                ) || ''
            )
            .toLowerCase();


        var status =
            (
                item.getValue(
                    'status'
                ) || ''
            )
            .toLowerCase();


        if (type === 'lost') {

            data.summary.lost++;

        }


        if (type === 'found') {

            data.summary.found++;

        }


        if (status === 'resolved') {

            data.summary.resolved++;

        }
        else {

            data.summary.active++;

        }


        /* ======================================
           CATEGORY COUNTS
        ====================================== */

        var categoryValue =
            item.getValue(
                'category'
            ) || 'other';


        var categoryDisplay =
            item.getDisplayValue(
                'category'
            ) || 'Other';


        if (
            !categoryMap[
                categoryValue
            ]
        ) {

            categoryMap[
                categoryValue
            ] = {

                value:
                    categoryValue,

                label:
                    categoryDisplay,

                total:
                    0,

                lost:
                    0,

                found:
                    0

            };

        }


        categoryMap[
            categoryValue
        ].total++;


        if (type === 'lost') {

            categoryMap[
                categoryValue
            ].lost++;

        }


        if (type === 'found') {

            categoryMap[
                categoryValue
            ].found++;

        }

    }


    /* ======================================================
       BUILD CATEGORY ARRAY
    ====================================================== */

    for (
        var categoryKey
        in categoryMap
    ) {

        if (
            categoryMap.hasOwnProperty(
                categoryKey
            )
        ) {

            data.categories.push(
                categoryMap[
                    categoryKey
                ]
            );

        }

    }


    data.categories.sort(
        function(a, b) {

            return (
                b.total -
                a.total
            );

        }
    );


    /* ======================================================
       MATCH ANALYTICS

       Only count records that actually contain a Match Engine
       overall score.

       Old/test records with no score are ignored.
    ====================================================== */

    var match =
        new GlideRecord(
            MATCH_TABLE
        );


    match.query();


    while (match.next()) {

        var rawScore =
            match.getValue(
                'overall_score'
            );


        /*
         * Ignore old/test records that were created
         * before the Match Engine generated scores.
         */
        if (
            rawScore === null ||
            rawScore === undefined ||
            rawScore.toString().trim() === ''
        ) {

            continue;

        }


        var overall =
            parseFloat(
                rawScore
            );


        /*
         * Extra protection against invalid values.
         */
        if (isNaN(overall)) {

            continue;

        }


        /*
         * Only now do we consider this a real
         * Match Engine record.
         */
        data.summary.totalMatches++;


        if (overall >= 80) {

            data.summary.strongMatches++;

        }
        else if (overall >= 65) {

            data.summary.potentialMatches++;

        }
        else {

            data.summary.lowMatches++;

        }

    }


    /* ======================================================
       CLAIM ANALYTICS
    ====================================================== */

    var claim =
        new GlideRecord(
            CLAIM_TABLE
        );


    claim.query();


    while (claim.next()) {

        data.summary.totalClaims++;


        var verification =
            (
                claim.getValue(
                    'u_verification_result'
                ) || ''
            )
            .toLowerCase();


        if (verification === 'pass') {

            data.summary.claimPass++;

        }


        if (verification === 'review') {

            data.summary.claimReview++;

        }


        if (verification === 'fail') {

            data.summary.claimFail++;

        }

    }

})();
